def count_convoys(target, position, speed):
    vans = sorted(zip(position, speed), reverse=True)
    convoys = 0
    lead = None
    for p, s in vans:
        d = target - p
        if lead is None or d * lead[1] >= lead[0] * s:
            convoys += 1
            lead = (d, s)
    return convoys

